PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS affiliate_platforms(id TEXT PRIMARY KEY, name TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)), policy_source TEXT, policy_checked_at TEXT);
CREATE TABLE IF NOT EXISTS affiliate_accounts(id TEXT PRIMARY KEY, platform_id TEXT NOT NULL REFERENCES affiliate_platforms(id), country TEXT NOT NULL DEFAULT 'MY', eligibility_evidence TEXT, enrollment_evidence TEXT, payment_evidence TEXT, owner_approved_at TEXT, enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)));
CREATE TABLE IF NOT EXISTS affiliate_products(id TEXT PRIMARY KEY, platform_id TEXT NOT NULL REFERENCES affiliate_platforms(id), product_identifier TEXT NOT NULL, name TEXT NOT NULL, category TEXT NOT NULL, price_sen INTEGER NOT NULL CHECK(price_sen>=0), commission_bps INTEGER CHECK(commission_bps BETWEEN 0 AND 10000), available INTEGER NOT NULL CHECK(available IN (0,1)), source_ref TEXT NOT NULL, source_at TEXT NOT NULL, compliance TEXT NOT NULL CHECK(compliance IN ('PENDING','VERIFIED','REJECTED')), campaign_status TEXT NOT NULL DEFAULT 'DRAFT', UNIQUE(platform_id,product_identifier));
CREATE TABLE IF NOT EXISTS affiliate_links(id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES affiliate_products(id), url TEXT NOT NULL, source_ref TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS content_ideas(id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES affiliate_products(id), topic TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS content_scripts(id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES affiliate_products(id), language TEXT NOT NULL CHECK(language IN ('ms','en')), body TEXT NOT NULL, disclosure TEXT NOT NULL, fingerprint TEXT UNIQUE NOT NULL, source_ref TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS media_assets(id TEXT PRIMARY KEY, script_id TEXT NOT NULL REFERENCES content_scripts(id), path TEXT NOT NULL, sha256 TEXT NOT NULL, rights_ref TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS publishing_queue(id TEXT PRIMARY KEY, script_id TEXT UNIQUE NOT NULL REFERENCES content_scripts(id), state TEXT NOT NULL CHECK(state IN ('DRAFT','VALIDATED','APPROVED','SCHEDULED','PUBLISHED','ANALYZED')), scheduled_at TEXT, manual_status TEXT, approved_by TEXT, approved_at TEXT, attempts INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS published_content(id TEXT PRIMARY KEY, queue_id TEXT UNIQUE NOT NULL REFERENCES publishing_queue(id), url TEXT UNIQUE NOT NULL, source_ref TEXT NOT NULL, published_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS campaign_metrics(id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL, content_id TEXT REFERENCES published_content(id), product_id TEXT REFERENCES affiliate_products(id), link_id TEXT REFERENCES affiliate_links(id), kind TEXT NOT NULL CHECK(kind IN ('clicks','views')), value INTEGER NOT NULL CHECK(value>=0), source_ref TEXT NOT NULL, source_at TEXT NOT NULL, UNIQUE(campaign_id,kind,source_ref,source_at));
CREATE TABLE IF NOT EXISTS affiliate_conversions(id TEXT PRIMARY KEY, platform_id TEXT NOT NULL REFERENCES affiliate_platforms(id), external_id TEXT NOT NULL, campaign_id TEXT NOT NULL, qualified INTEGER NOT NULL CHECK(qualified IN (0,1)), sales_sen INTEGER NOT NULL CHECK(sales_sen>=0), source_ref TEXT NOT NULL, source_at TEXT NOT NULL, UNIQUE(platform_id,external_id));
CREATE TABLE IF NOT EXISTS commission_records(id TEXT PRIMARY KEY, conversion_id TEXT NOT NULL UNIQUE REFERENCES affiliate_conversions(id), amount_sen INTEGER NOT NULL CHECK(amount_sen>=0), status TEXT NOT NULL CHECK(status IN ('PENDING','APPROVED','REJECTED')), source_ref TEXT NOT NULL, source_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payout_records(id TEXT PRIMARY KEY, platform_id TEXT NOT NULL REFERENCES affiliate_platforms(id), external_id TEXT NOT NULL, amount_sen INTEGER NOT NULL CHECK(amount_sen>=0), source_ref TEXT NOT NULL, source_at TEXT NOT NULL, UNIQUE(platform_id,external_id));
CREATE TABLE IF NOT EXISTS payout_allocations(payout_id TEXT NOT NULL REFERENCES payout_records(id), commission_id TEXT NOT NULL REFERENCES commission_records(id), amount_sen INTEGER NOT NULL CHECK(amount_sen>0), PRIMARY KEY(payout_id,commission_id));
CREATE TABLE IF NOT EXISTS operating_expenses(id TEXT PRIMARY KEY, amount_sen INTEGER NOT NULL CHECK(amount_sen>=0), kind TEXT NOT NULL CHECK(kind IN ('EXPENSE','PLATFORM_CHARGE')), source_ref TEXT NOT NULL, source_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS automation_jobs(id TEXT PRIMARY KEY, kind TEXT NOT NULL, scheduled_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('PENDING','RUNNING','AWAITING_APPROVAL','COMPLETED','FAILED','PAUSED','DISABLED')), retry_count INTEGER NOT NULL DEFAULT 0, max_retries INTEGER NOT NULL DEFAULT 3, next_attempt_at TEXT, last_success_at TEXT, error_code TEXT, source_refs TEXT NOT NULL DEFAULT '[]', approval_required INTEGER NOT NULL DEFAULT 1, completion_evidence TEXT, lease_until TEXT);
CREATE TABLE IF NOT EXISTS automation_executions(id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES automation_jobs(id), started_at TEXT NOT NULL, finished_at TEXT, status TEXT NOT NULL, error_code TEXT);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, kind TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL, read_at TEXT, dedupe_key TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS approval_requests(id TEXT PRIMARY KEY, entity_id TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', evidence TEXT, approved_by TEXT, approved_at TEXT);
CREATE TABLE IF NOT EXISTS integration_status(id TEXT PRIMARY KEY, status TEXT NOT NULL, evidence TEXT, checked_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT, actor TEXT NOT NULL, action TEXT NOT NULL, entity_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS usage_buckets(period TEXT PRIMARY KEY, executions INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS jobs_due ON automation_jobs(status,next_attempt_at,scheduled_at);
CREATE INDEX IF NOT EXISTS financial_source ON commission_records(source_at,status);
CREATE INDEX IF NOT EXISTS queue_schedule ON publishing_queue(state,scheduled_at);
INSERT OR IGNORE INTO settings VALUES('paused','1');
INSERT OR IGNORE INTO affiliate_platforms(id,name) VALUES('shopee-my','Shopee Affiliate Malaysia'),('tiktok-my','TikTok Shop Affiliate Malaysia');
